import type {
  DirectionAddress,
  DirectionCandidate,
  DirectionRef,
  DirectionResolution,
  DirectionSearchAddress,
} from '../types/direction-ref';
import type {
  VariantHistoryManifest,
  VariantHistoryStatus,
} from '../types/variant-history';

const SLUG_MAX_LENGTH = 40;
const EMPTY_LABEL_SLUG = 'direction';
const LAST_KEYWORD = 'last';
const FIRST_COLLISION_SUFFIX = 2;
const MIN_VARIANT_ID_PREFIX_LENGTH = 4;
const MAX_UNKNOWN_CANDIDATES = 10;
const TOKEN_PATTERN = /^[A-Za-z0-9_-]+$/;
const INACTIVE_STATUSES: ReadonlySet<VariantHistoryStatus> = new Set([
  'removed',
  'cancelled',
]);

export const isDirectionActive = (status: VariantHistoryStatus): boolean =>
  !INACTIVE_STATUSES.has(status);

type DirectionRefSource = {
  manifest: Pick<
    VariantHistoryManifest,
    'sessionId' | 'variantId' | 'label' | 'createdAt' | 'directionRef'
  >;
};

export const slugifyDirectionLabel = (label: string): string => {
  const slug = label
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  if (!slug) return EMPTY_LABEL_SLUG;
  if (slug.length <= SLUG_MAX_LENGTH) return slug;
  const boundary = slug.lastIndexOf('-', SLUG_MAX_LENGTH);
  return slug.slice(0, boundary > 0 ? boundary : SLUG_MAX_LENGTH);
};

export const nextDirectionRef = (args: {
  label: string;
  taken: ReadonlySet<string>;
}): DirectionRef => {
  const slug = slugifyDirectionLabel(args.label);
  const isTaken = (candidate: string): boolean =>
    candidate === LAST_KEYWORD || args.taken.has(candidate);
  let candidate = slug;
  for (let suffix = FIRST_COLLISION_SUFFIX; isTaken(candidate); suffix++)
    candidate = `${slug}-${suffix}`;
  return candidate as DirectionRef;
};

const directionKey = (manifest: DirectionRefSource['manifest']): string =>
  `${manifest.sessionId}:${manifest.variantId}`;

const byCreation = (a: DirectionRefSource, b: DirectionRefSource): number =>
  a.manifest.createdAt.localeCompare(b.manifest.createdAt) ||
  a.manifest.sessionId.localeCompare(b.manifest.sessionId) ||
  a.manifest.variantId.localeCompare(b.manifest.variantId);

export const withDirectionRefs = <Entry extends DirectionRefSource>(
  entries: readonly Entry[],
): Array<Entry & { directionRef: DirectionRef }> => {
  const taken = new Set<string>(
    entries.flatMap(({ manifest }) =>
      manifest.directionRef ? [manifest.directionRef] : [],
    ),
  );
  const legacyRefs = new Map<string, DirectionRef>();
  const legacyRefOf = (manifest: DirectionRefSource['manifest']) => {
    const key = directionKey(manifest);
    const known = legacyRefs.get(key);
    if (known) return known;
    const directionRef = nextDirectionRef({ label: manifest.label, taken });
    taken.add(directionRef);
    legacyRefs.set(key, directionRef);
    return directionRef;
  };
  for (const { manifest } of [...entries].sort(byCreation))
    if (!manifest.directionRef) legacyRefOf(manifest);
  return entries.map((entry) => ({
    ...entry,
    directionRef: entry.manifest.directionRef ?? legacyRefOf(entry.manifest),
  }));
};

const parseDirectionIds = (raw: string): DirectionAddress | null => {
  const projectSeparator = raw.indexOf('/');
  const projectId =
    projectSeparator === -1 ? undefined : raw.slice(0, projectSeparator);
  const direction =
    projectSeparator === -1 ? raw : raw.slice(projectSeparator + 1);
  if (projectSeparator !== -1 && (!projectId || direction.includes('/')))
    return null;
  const variantSeparator = direction.indexOf(':');
  if (variantSeparator <= 0 || variantSeparator === direction.length - 1)
    return null;
  if (direction.indexOf(':', variantSeparator + 1) !== -1) return null;
  const sessionId = direction.slice(0, variantSeparator).trim();
  const variantId = direction.slice(variantSeparator + 1).trim();
  if (!sessionId || !variantId) return null;
  return {
    kind: 'ids',
    ...(projectId ? { projectId } : {}),
    sessionId,
    variantId,
  };
};

export const parseDirectionAddress = (raw: string): DirectionAddress | null => {
  const value = raw.trim();
  if (value.toLowerCase() === LAST_KEYWORD) return { kind: 'last' };
  if (value.includes(':') || value.includes('/'))
    return parseDirectionIds(value);
  return TOKEN_PATTERN.test(value) ? { kind: 'token', token: value } : null;
};

const newestFirst = (a: DirectionCandidate, b: DirectionCandidate): number =>
  b.createdAt.localeCompare(a.createdAt);

const notFound = (args: {
  input: string;
  newest: DirectionCandidate[];
}): DirectionResolution => {
  const candidates = args.newest.slice(0, MAX_UNKNOWN_CANDIDATES);
  const knownRefs = candidates.map((candidate) => candidate.directionRef);
  const knownRefsSentence =
    knownRefs.length > 0 ? ` Known refs: ${knownRefs.join(', ')}.` : '';
  return {
    isResolved: false,
    code: 'WORK_ITEM_NOT_FOUND',
    message: `No direction matches "${args.input}".${knownRefsSentence}`,
    candidates,
  };
};

const resolveToken = (args: {
  token: string;
  newest: DirectionCandidate[];
}): DirectionResolution => {
  const needle = args.token.toLowerCase();
  const exact = args.newest.filter(
    (candidate) => candidate.directionRef.toLowerCase() === needle,
  );
  const prefixed =
    needle.length >= MIN_VARIANT_ID_PREFIX_LENGTH
      ? args.newest.filter((candidate) =>
          candidate.variantId.toLowerCase().startsWith(needle),
        )
      : [];
  const matches = exact.length > 0 ? exact : prefixed;
  if (matches.length === 1) return { isResolved: true, direction: matches[0] };
  if (matches.length === 0)
    return notFound({ input: args.token, newest: args.newest });
  return {
    isResolved: false,
    code: 'DIRECTION_AMBIGUOUS',
    message: `"${args.token}" matches ${matches.length} directions: ${matches
      .map((candidate) => candidate.directionRef)
      .join(', ')}.`,
    candidates: matches,
  };
};

export const resolveDirectionAddress = (args: {
  address: DirectionSearchAddress;
  candidates: readonly DirectionCandidate[];
}): DirectionResolution => {
  const newest = [...args.candidates].sort(newestFirst);
  switch (args.address.kind) {
    case 'last': {
      const direction = newest.find((candidate) =>
        isDirectionActive(candidate.status),
      );
      return direction
        ? { isResolved: true, direction }
        : notFound({ input: LAST_KEYWORD, newest });
    }
    case 'token':
      return resolveToken({ token: args.address.token, newest });
    default: {
      const unhandled: never = args.address;
      return unhandled;
    }
  }
};
